    [('98 vs 49', '故障注入在前与限流在前时,通过的(200)请求数(429 分别是 99 和 301)'), ('300 / 300 vs 19 / 300', '/health(路由级覆盖)与 /api(过滤器级配置)通过限流的请求数'), ('+51 µs', 'router 之前多了 20 个简单 Lua 过滤器后,p50 延迟相对没有 Lua 过滤器的增加')],
